package com.bank.recon;

// Epsilon comparison for the APPROXIMATE (non-money) case only.
class ToleranceComparator {
    private final double epsilon;

    ToleranceComparator(double epsilon) { this.epsilon = epsilon; }

    // Near-equal within a small absolute tolerance.
    boolean nearlyEqual(double a, double b) {
        return Math.abs(a - b) < epsilon;
    }
}
