package com.bank.recon;

import java.math.BigDecimal;

// Shows the WRONG double path and the CORRECT BigDecimal path.
class ReconciliationService {

    // WRONG for money: doubles accumulate binary rounding error.
    boolean balancesUsingDouble(double a, double b, double expected) {
        return (a + b) == expected; // exact equality on doubles — fragile
    }

    // CORRECT for money: BigDecimal from STRINGS gives exact decimal math.
    boolean balancesUsingBigDecimal(String a, String b, String expected) {
        BigDecimal sum = new BigDecimal(a).add(new BigDecimal(b));
        // compareTo (not equals) so scale differences like 0.30 vs 0.3 match.
        return sum.compareTo(new BigDecimal(expected)) == 0;
    }

    // The TRAP: constructing BigDecimal from a double captures the binary error.
    BigDecimal fromDoubleTrap(double value) {
        return new BigDecimal(value); // DON'T do this with money
    }

    BigDecimal fromStringCorrect(String value) {
        return new BigDecimal(value); // DO this
    }
}
