package com.bank.recon;

import java.math.BigDecimal;
import java.util.logging.*;

public class FloatingPointDemo {
    private static final Logger log = Logger.getLogger(FloatingPointDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ReconciliationService svc = new ReconciliationService();

        // 1) The famous false result and the visible trailing error.
        boolean naive = (0.1 + 0.2) == 0.3;
        log.info(() -> "0.1 + 0.2 == 0.3  -> " + naive + "  (IEEE 754)");
        log.info(() -> "0.1 + 0.2 prints  -> " + (0.1 + 0.2) + "  (trailing error visible)");

        // 2) Double-based reconciliation falsely fails.
        boolean dblOk = svc.balancesUsingDouble(0.1, 0.2, 0.3);
        log.warning(() -> "Double reconciliation balanced? " + dblOk + "  (FALSE — wrong!)");

        // 3) Epsilon tolerance — correct for the approximate (non-money) case.
        ToleranceComparator tol = new ToleranceComparator(1e-9);
        boolean near = tol.nearlyEqual(0.1 + 0.2, 0.3);
        log.info(() -> "Tolerance nearlyEqual(0.1+0.2, 0.3)? " + near + "  (OK for analytics)");

        // 4) BigDecimal from strings — exact, correct for MONEY.
        boolean bdOk = svc.balancesUsingBigDecimal("0.1", "0.2", "0.3");
        log.info(() -> "BigDecimal reconciliation balanced? " + bdOk + "  (TRUE — exact)");

        // 5) The BigDecimal-from-double trap vs the string-correct way.
        BigDecimal trap = svc.fromDoubleTrap(0.1);
        BigDecimal good = svc.fromStringCorrect("0.1");
        log.warning(() -> "new BigDecimal(0.1) -> " + trap + "  (captures binary error!)");
        log.info(() -> "new BigDecimal(\"0.1\") -> " + good + "  (exact)");
    }
}

